const markPurgedDependencies = `-- name: MarkPurgedDependencies :many
UPDATE meta.fields SET
  options=jsonb_set(options,'{error}','"dependency_missing"'::jsonb), version=version+1
WHERE table_id<>ALL($1::uuid[]) AND deleted_at IS NULL AND ui_type IN ('lookup','rollup')
  AND (options->>'relationFieldId'=ANY($2::text[])
       OR options->>'targetFieldId'=ANY($2::text[]))
RETURNING table_id
`

type MarkPurgedDependenciesParams struct {
	TableIds []pgtype.UUID
	FieldIds []string
}

func (q *Queries) MarkPurgedDependencies(ctx context.Context, arg MarkPurgedDependenciesParams) ([]pgtype.UUID, error) {
	rows, err := q.db.Query(ctx, markPurgedDependencies, arg.TableIds, arg.FieldIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []pgtype.UUID
	for rows.Next() {
		var table_id pgtype.UUID
		if err := rows.Scan(&table_id); err != nil {
			return nil, err
		}
		items = append(items, table_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

